def encode(message):
    vowels = 'aeiouAEIOU'
    result = []

    for char in message:
        if char.isalpha():
            # Swap case
            swapped_char = char.swapcase()

            # Check if it's a vowel and replace with letter 2 places ahead
            original_lower = char.lower()
            if original_lower in 'aeiou':
                index = ord(original_lower) - ord('a')
                new_index = (index + 2) % 26
                replacement_char = chr(new_index + ord('a'))

                # Determine case of the replacement character based on original char's case
                if swapped_char.isupper():
                    result.append(replacement_char.upper())
                else:
                    result.append(replacement_char.lower())
            else:
                result.append(swapped_char)
        else:
            result.append(char)

    return ''.join(result)

